import logging
import six
from ute_common_abstract_core import logger as core_logger


THROUGHPUT_UNIT = 'k'


class DataTransferConfig(object):

    def __init__(self, dt_definition, configuration, **kwargs):
        """
        Data transfer settings from DataTransferDefinition (robot kwargs).
        :param dt_definition: object that encapsulates all needed parameters
        :type dt_definition: DataTransferDefinition class object
        :param configuration: configuration of MediaTek UE
        :type configuration: dict
        """
        self._serial_number = configuration.get('serial_number', None)
        self._data_transfer = configuration.get('data_transfer', {})
        self._dt_definition = {'duration': dt_definition.duration,
                               'protocol': dt_definition.protocol,
                               'protocol_details': dt_definition.protocol_details,
                               'bandwidth': '{}{}'.format(int(dt_definition.throughput), THROUGHPUT_UNIT)}
        self._configuration = configuration
        self._protocol_details = self._dt_definition.get('protocol_details', {})

    @property
    def dt_definition(self):
        return self._dt_definition

    @property
    def protocol_details(self):
        return self._protocol_details

    @property
    def serial_number(self):
        return self._serial_number

    @property
    def test_logs_dir(self):
        return core_logger.get_logging_path()

    @property
    def version(self):
        version = self._configuration["data_transfer"].get("version", "2")
        if version not in ("2", "3"):
            version = "2"
        return version


class UeDataTransferConfig(DataTransferConfig):

    def __init__(self, dt_definition, configuration, ue_ip):
        """
        Iperf data transfer settings from DataTransferDefinition (robot kwargs).
        :param dt_definition: object that encapsulates all needed parameters
        :type dt_definition: DataTransferDefinition class object
        :param configuration: configuration of MediaTek UE
        :type configuration: dict
        """
        super(UeDataTransferConfig, self).__init__(dt_definition, configuration)
        self._ue_ip = ue_ip
        self._uepc_config = self._data_transfer['ue_host']

    @property
    def host_config(self):
        return self._uepc_config

    @property
    def iperf_path(self):
        return self._uepc_config['iperf_path']

    @property
    def bind(self):
        return self._ue_ip

    @property
    def connection(self):
        connection_params = {
            k: v
            for k, v in dict(host=self._uepc_config['addr'],  # noqa C408
                             username=self._uepc_config['username'],
                             password=self._uepc_config['password']).items()
            if v is not None}
        return connection_params


class AppserverDataTransferConfig(DataTransferConfig):

    _APPSERVER_NODE_NAME = "APPSERVER"

    def __init__(self, dt_definition, configuration, appserver_name):
        """
        Iperf data transfer settings from DataTransferDefinition (robot kwargs).
        :param dt_definition: object that encapsulates all needed parameters
        :type dt_definition: DataTransferDefinition class object
        :param configuration: configuration of MediaTek UE
        :type configuration: dict
        :param appserver_name: appserver configuration
        :type appserver_name: str or dict or Testline object
        """
        super(AppserverDataTransferConfig, self).__init__(dt_definition, configuration)
        self._appserver_config = None
        self._appserver_name = appserver_name if appserver_name else 'app_server'
        self._update_appservers_config(configuration)

    def _update_appservers_config(self, configuration):
        if self._APPSERVER_NODE_NAME in configuration:
            self._data_transfer.update(configuration[self._APPSERVER_NODE_NAME])
        if isinstance(self._appserver_name, six.string_types):
            self._appserver_config = self._data_transfer[self._appserver_name]
            return
        if isinstance(self._appserver_name, dict):
            port = self.protocol_details.get('port', 5001)
            self._appserver_config = {
                'addr': self._appserver_name['host']['host'],
                'username': self._appserver_name['host']['login'],
                'password': self._appserver_name['host']['password'],
                'iperf_ports': [port, ],
                'iperf_path': self._appserver_name['iperf']['path'],
                'iperf_interface_ip': self._appserver_name['bind_interface_ip']
            }
        else:
            self._appserver_config = {
                'addr': self._appserver_name.iperf_details.ssh_connection_details.addr,
                'username': self._appserver_name.iperf_details.ssh_connection_details.username,
                'password': self._appserver_name.iperf_details.ssh_connection_details.password,
                'iperf_ports': self._appserver_name.iperf_details.ports,
                'iperf_path': self._appserver_name.iperf_details.iperf_path,
                'iperf_interface_ip': self._appserver_name.iperf_details.network_interface_address
            }

    @property
    def host_config(self):
        return self._appserver_config

    @property
    def iperf_path(self):
        return self._appserver_config['iperf_path']

    @property
    def bind(self):
        return self._appserver_config['iperf_interface_ip']

    @property
    def connection(self):
        connection_params = {
            k: v
            for k, v in dict(host=self._appserver_config['addr'],  # noqa C408
                             username=self._appserver_config['username'],
                             password=self._appserver_config['password']).items()
            if v is not None}
        return connection_params


class IperfDataTransferOptionsFactory(object):

    def __init__(self):
        self._configuration = None
        self._dt_definition = None
        self.dt_config = None

    @property
    def direction(self):
        """Direction of data transfer ('ul', 'dl')"""
        return self._dt_definition.direction

    def create_iperf_server_options(self, config, dt_definition, port, bind=None):
        self._configuration = config
        self._dt_definition = dt_definition
        self.dt_config = self._init_dt_config(port)

        iperf_version = self.dt_config["version"]

        if iperf_version == "2":
            return self._create_iperf2_server_options(bind)

        return self._create_iperf3_server_options(bind)

    def create_iperf_client_options(self, config, dt_definition, port, bind=None, client=None):
        self._configuration = config
        self._dt_definition = dt_definition
        self.dt_config = self._init_dt_config(port)

        iperf_version = self.dt_config["version"]

        if iperf_version == "2":
            return self._create_iperf2_client_options(bind, client)

        return self._create_iperf3_client_options(bind, client)

    def _init_dt_config(self, iperf_port):
        protocol_details = self._dt_definition.protocol_details
        dt_config = {
            "app_server": {
                "host_configuration": {
                    "host": self._configuration["data_transfer"]["app_server"]["addr"],
                    "username": self._configuration["data_transfer"]["app_server"]["username"],
                    "password": self._configuration["data_transfer"]["app_server"]["password"]},
                "mode": "server" if self.direction == "ul" else "client",
                "binary_path": self._configuration["data_transfer"]["app_server"]["iperf_path"]},
            "ue_host": {
                "mode": "server" if self.direction == "dl" else "client",
                "binary_path": self._configuration["data_transfer"]["ue_host"]["iperf_path"]},
            "version": self._configuration["data_transfer"].get("version", "2"),
            "protocol": self._dt_definition.protocol,
            "time": self._dt_definition.duration,
            "bandwidth": "{}{}".format(self._dt_definition.throughput, THROUGHPUT_UNIT),
            "port": iperf_port,
            "length": protocol_details.get("packet", None) or protocol_details.get("packet_size", None),
            "interval": protocol_details.get("interval", 1),
            "parallel": protocol_details.get("parallel", None) or protocol_details.get("parallel_streams", None) or   # noqa W504
                        protocol_details.get("parallel_thread", None),  # noqa E131
            "ttl": protocol_details.get("ttl", None),
            "window": protocol_details.get("buffer", None),
            "max_segment_size": protocol_details.get("max_segment_size", None),
            "reverse": protocol_details.get("reverse", None),
            "linux_congestion": protocol_details.get("linux_congestion", None),
        }
        logging.debug("dt_config: {}".format(dt_config))
        return dt_config

    def _create_iperf_common_options(self, bind):
        options = "-p {} -i {} -f k ".format(self.dt_config["port"], self.dt_config["interval"])
        if bind is not None:
            options += '-B {bind} '.format(bind=bind)
        return options

    def _create_iperf2_common_options(self, bind):
        options = ""
        if self.dt_config["protocol"] == "udp":
            options = "-u "
        options += self._create_iperf_common_options(bind)

        if self.dt_config["length"] is not None:
            options += "-l {} ".format(self.dt_config["length"])
        if self.dt_config["max_segment_size"] is not None:
            options += "-M {} ".format(self.dt_config["max_segment_size"])
        if self.dt_config["window"] is not None:
            options += "-w {} ".format(self.dt_config["window"])
        return options

    def _create_iperf2_client_options(self, bind, client):
        options = "-c {} ".format(client)
        options += self._create_iperf2_common_options(bind)
        options += "-t {} ".format(self.dt_config["time"])
        if "-u" in options:
            options += "-b {} ".format(self.dt_config["bandwidth"])

        if self.dt_config["parallel"] is not None:
            options += "-P {} ".format(self.dt_config["parallel"])
        if self.dt_config["ttl"] is not None:
            options += "-T {} ".format(self.dt_config["ttl"])
        if self.dt_config["linux_congestion"] is not None:
            options += "-Z {} ".format(self.dt_config["linux_congestion"])
        return options

    def _create_iperf2_server_options(self, bind):
        options = "-s "
        options += self._create_iperf2_common_options(bind)
        return options

    def _create_iperf3_client_options(self, bind, client):  # noqa C901
        options = "-c {} ".format(client)
        if self.dt_config["protocol"] == "udp":
            options += "-u "
        options += self._create_iperf_common_options(bind)
        options += "-t {} ".format(self.dt_config["time"])
        options += "-b {} ".format(self.dt_config["bandwidth"])

        if self.dt_config["length"] is not None:
            options += "-l {} ".format(self.dt_config["length"])
        if self.dt_config["max_segment_size"] is not None:
            options += "-M {} ".format(self.dt_config["max_segment_size"])
        if self.dt_config["window"] is not None:
            options += "-w {} ".format(self.dt_config["window"])
        if self.dt_config["parallel"] is not None:
            options += "-P {} ".format(self.dt_config["parallel"])
        if self.dt_config["reverse"] is not None:
            options += "-R {} ".format(self.dt_config["reverse"])
        if self.dt_config["linux_congestion"] is not None:
            options += "-C {} ".format(self.dt_config["linux_congestion"])
        return options

    def _create_iperf3_server_options(self, bind):
        options = "-s "
        options += self._create_iperf_common_options(bind)
        return options
